    <style>
      :root {
        color-scheme: dark;
        --bg: #0f172a;
        --surface: #111827;
        --surface-2: #1f2937;
        --text: #f8fafc;
        --muted: #cbd5e1;
        --border: #334155;
        --accent: #38bdf8;
        --accent-strong: #0ea5e9;
        --shadow: #020617;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-height: 100%;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #1e293b 0, var(--bg) 45%),
          var(--bg);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border: 2px solid var(--accent);
        border-radius: 0.75rem;
        background: var(--surface);
        color: var(--text);
        transform: translateY(-160%);
        transition: transform 0.2s ease;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 5rem 1rem 2rem;
      }

      .card {
        width: min(100%, 30rem);
        padding: 2rem;
        border: 1px solid var(--border);
        border-radius: 1.25rem;
        background: linear-gradient(180deg, #111827 0%, #0b1220 100%);
        box-shadow: 0 24px 70px var(--shadow);
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(1.6rem, 3vw, 2rem);
        line-height: 1.2;
      }

      .description {
        margin: 0 0 1.5rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: var(--surface);
      }

      .checkbox-row {
        display: flex;
        gap: 0.75rem;
        align-items: flex-start;
      }

      input[type="checkbox"] {
        width: 1.125rem;
        height: 1.125rem;
        margin-top: 0.15rem;
        accent-color: var(--accent);
        flex: none;
      }

      label {
        display: block;
        font-weight: 600;
      }

      .required {
        color: var(--accent);
      }

      .helper-text {
        margin: 0.35rem 0 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      button {
        appearance: none;
        border: 1px solid var(--accent-strong);
        border-radius: 0.9rem;
        padding: 0.9rem 1.1rem;
        background: linear-gradient(180deg, var(--accent) 0%, var(--accent-strong) 100%);
        color: #082f49;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition: transform 0.15s ease, filter 0.15s ease;
      }

      button:hover {
        filter: brightness(1.05);
      }

      button:active {
        transform: translateY(1px);
      }

      :focus-visible {
        outline: 3px solid #f8fafc;
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--muted);
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-2: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --accent: Highlight;
          --accent-strong: Highlight;
          --shadow: Canvas;
        }

        .card,
        .form-field {
          border-color: ButtonBorder;
        }

        button {
          color: ButtonText;
          background: ButtonFace;
          border-color: ButtonText;
        }
      }

      @media (max-width: 420px) {
        .card {
          padding: 1.25rem;
        }
      }
    </style>
