        const el = document.createElement(tag);
        for (const [key, value] of Object.entries(props)) {
          if (key === "className") {
            el.className = value;
          } else if (key === "textContent") {
            el.textContent = value;
          } else if (key.startsWith("aria-") || key === "for" || key === "type" || key === "id" || key === "name" || key === "required" || key === "href" || key === "method" || key === "action" || key === "autocomplete" || key === "novalidate") {
            if (value === true) {
              el.setAttribute(key, "");
            } else if (value !== false && value != null) {
              el.setAttribute(key, value);
            }
          } else if (key in el) {
            el[key] = value;
          } else if (value !== false && value != null) {
            el.setAttribute(key, value);
          }
        }
        for (const child of children.flat()) {
          if (child == null) continue;
          el.append(child.nodeType ? child : document.createTextNode(child));
        }
        return el;
      };

      function ConsentField() {
        const checkbox = h("input", {
          id: "agreeTerms",
          type: "checkbox",
          name: "agreeTerms",
          required: true,
          "aria-describedby": "terms-help",
        });

        const label = h(
          "label",
          { for: "agreeTerms" },
          "I agree to the terms of use ",
          h("span", { className: "required", textContent: "*" })
        );

        const help = h("p", {
          id: "terms-help",
          className: "helper-text",
          textContent: "You must agree before submitting.",
        });

        return h(
          "div",
          { className: "form-field" },
          h(
            "div",
            { className: "checkbox-row" },
            checkbox,
            h("div", {}, label, help)
          )
        );
      }

      function App() {
        const status = h("p", {
          className: "status",
          id: "form-status",
          "aria-live": "polite",
          textContent: "",
        });

        const form = h(
          "form",
          {
            method: "post",
            action: "#",
          },
          ConsentField(),
          h("button", { type: "submit", textContent: "Submit" }),
          status
        );

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          status.textContent = "Thanks — your consent has been recorded.";
        });

        return h(
          "section",
          { className: "card", "aria-labelledby": "page-title" },
          h("h1", { id: "page-title", textContent: "Consent to Terms of Use" }),
          h("p", {
            className: "description",
            textContent: "Review the checkbox below and submit only if you agree.",
          }),
          form
        );
      }

      document.getElementById("main").append(App());
    </script>
  </body>
</html>
